('839f9d59-cf3c-5eaf-8aa1-918a4bf02de1', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Uma String Java é:', '["Um primitivo.","Um objeto imutável.","Uma thread.","Um array char sempre mutável exposto.","Um arquivo de texto."]'::jsonb, 1, 'Operações de transformação não alteram o conteúdo do objeto original.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.2, páginas 507 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('42a168d2-6500-5f42-8eb3-255815392e15', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Difícil', 'Após `String s="java"; s.toUpperCase();`, qual conteúdo de s?', '["java.","null.","Java.","JAVA.","Erro."]'::jsonb, 0, 'O resultado foi ignorado; s mantém a referência anterior.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('851365e4-4bcd-5553-a2ec-a3241c3b957c', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Para comparar conteúdo de duas strings, usa-se tipicamente:', '["instanceof.","=.","== como garantia geral de conteúdo.","equals.","hashCode como igualdade suficiente."]'::jsonb, 3, '== compara identidade das referências, não conteúdo textual em geral.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8876f222-0776-552b-a9f2-7a91aa72f732', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Difícil', 'O que `new String("abc")==new String("abc")` produz?', '["true.","false.","0.","null.","Erro."]'::jsonb, 1, 'As duas construções criam objetos diferentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('730c7ed5-4afd-58ec-b04d-23adfa96b5e5', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'O que `new String("abc").equals(new String("abc"))` produz?', '["false.","null.","Erro.","true.","3."]'::jsonb, 3, 'Equals de String compara o conteúdo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c127e638-3ea1-5ebe-8ff5-59beeb6a4236', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Qual resultado de `"navio".substring(1,4)`?', '["av.","avio.","vio.","nav.","avi."]'::jsonb, 4, 'O início é inclusivo e o fim exclusivo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1e9ff411-3c93-5c34-98fe-5e2918bfdec6', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Qual resultado de `"Java".charAt(2)`?', '["J.","a.","2.","Erro.","v."]'::jsonb, 4, 'Os índices começam em zero.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2a3876c4-b4a8-569d-ace2-56b171dcd46d', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Qual resultado de `"banana".indexOf("na")`?', '["2.","-1.","3.","4.","0."]'::jsonb, 0, 'IndexOf retorna o índice inicial da primeira ocorrência.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('272ef7b4-719c-594d-aa58-31d72f7b5a51', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Quando indexOf não encontra o trecho, retorna:', '["O comprimento mais um.","null.","-1.","0 sempre.","Uma string vazia."]'::jsonb, 2, 'Zero é índice válido e não indica ausência.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('13c421c9-44c3-5f3c-8449-d3143495658d', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Qual resultado de `"abc".compareTo("abd")` quanto ao sinal?', '["Sempre 1.","Zero.","Erro.","Negativo.","Positivo."]'::jsonb, 3, 'A comparação lexicográfica detecta c antes de d.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9ae2fa2d-8018-5ef6-8c59-1bc6c0fabc1f', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', '`"A".equalsIgnoreCase("a")` produz:', '["false.","null.","true.","Um char.","Erro."]'::jsonb, 2, 'A comparação desconsidera diferenças de caixa conforme a operação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('054f850c-a060-5dd8-9d69-549252a03d78', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Difícil', 'Qual resultado de `"a" + 2 + 3`?', '["a23.","5a.","a5.","a6.","Erro."]'::jsonb, 0, 'A concatenação ocorre da esquerda para a direita.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f8046e5-8bbb-5a20-baa6-6449fb5b6285', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Difícil', 'Qual resultado de `2 + 3 + "a"`?', '["a23.","23a.","Erro.","a5.","5a."]'::jsonb, 4, 'A soma numérica é avaliada antes da concatenação textual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.3, páginas 508–516 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('62cbca1f-b149-5b36-81bd-1f24ed61855f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'StringBuilder é adequado para:', '["Criar strings primitivas.","Definir threads.","Construir texto por operações mutáveis.","Garantir sincronização de todos os métodos.","Executar regex exclusivamente."]'::jsonb, 2, 'Ele evita criar um novo String a cada alteração de seu conteúdo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.4, páginas 517–522 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8c1b92af-691d-51c3-a101-dccf9397ed2c', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Após append de "A" e depois "B" em um StringBuilder vazio, o texto é:', '["BA.","Erro.","A apenas.","A B.","AB."]'::jsonb, 4, 'Append acrescenta ao final do conteúdo atual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.4, páginas 517–522 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('adf2094d-0f84-5a95-8d47-13abf2739d84', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Qual método StringBuilder inverte a sequência de caracteres?', '["sort().","reverse().","rotate().","shuffle().","invertCase()."]'::jsonb, 1, 'Reverse é uma operação mutável do construtor de texto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.4, páginas 517–522 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('91d54835-5b50-5a6d-9351-0ba16f5db91a', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Character.isDigit(''7'') resulta em:', '["true.","false.","Erro.","null.","7 como int."]'::jsonb, 0, 'O método testa se o caractere representa um dígito.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.5, páginas 523–525 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c99972ba-a699-5d27-a5c0-60853a8cd75a', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Difícil', 'String.split usa seu argumento principalmente como:', '["Quantidade obrigatória de caracteres.","Índice final exclusivo.","Nome de pacote.","Expressão regular delimitadora.","Chave de mapa."]'::jsonb, 3, 'Metacaracteres precisam ser escapados quando se quer um delimitador literal.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.6, páginas 526 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7d24b80d-1a28-5e04-b18a-3694e051bb47', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'String.matches testa normalmente:', '["A igualdade de hashCode.","Se a string inteira corresponde à expressão.","A identidade de referência.","Somente uma ocorrência parcial sempre.","Somente a primeira letra."]'::jsonb, 1, 'Busca parcial pode ser feita com operações de Matcher como find.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.7, páginas 527–532 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('98a07a1f-4111-5002-880f-0ad748e61635', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Em Matcher, find busca principalmente:', '["Uma thread.","Um arquivo.","Uma próxima subsequência correspondente.","Apenas correspondência da string inteira.","Somente igualdade de objetos."]'::jsonb, 2, 'Find permite localizar ocorrências sucessivas no texto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 14, seção 14.7, páginas 527–532 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
